{
  "story": "How does RAG answer using outside information? Start with a question and two fixed policy passages. Advance to compare retrieval scores, select evidence, and inspect the augmented prompt. At Grounded answer, compare the cited response with its source; that state stays visible until you act.",
  "aha": {
    "stateId": "grounded-answer",
    "observation": "RAG supplies retrieved source text alongside the question, allowing the generated answer to cite evidence without updating model weights."
  },
  "layout": {
    "preset": "stepper-states/pipeline",
    "width": 640
  },
  "parts": [
    {
      "id": "pipeline-rail",
      "kind": "step-rail",
      "presentation": "Use the approved card shell with story and instructions above the experiment. Keep progress and trace on this rail, without a clock. Parameter-control budget: zero; navigation and Reset are separate. Preserve readable labels at native width.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "rag-picture",
      "kind": "fixed-picture",
      "presentation": "Use the canonical RAG pipeline arrangement with fixed topology and wrapped rows. Keep named regions and source text visible throughout. Region descriptions identify roles, not completed outputs. Highlight the bound active regions. Use shared, unscaled boxes; box size encodes no quantity.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "active-explanation",
      "kind": "active-callout",
      "presentation": "Anchor the explanation to the named active region. Identify where the mechanism occurs; leave measurements in readouts. Reserve enough label space for every state.",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "evidence-readouts",
      "kind": "value-readout",
      "presentation": "Show bound values beneath the picture, wrapping text without truncation. Render Status as the final persistent row. Scores use exact distinct-token counts with no rounding. Both passages share the same query, tokenization, and score scale. Source identifiers connect quotations, prompt context, and citations.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "pipeline-step",
      "kind": "index",
      "items": "variant.states",
      "label": "RAG pipeline navigation",
      "presentation": "Buttons are named Previous and Next; ArrowLeft and ArrowRight operate them. Default: first state; increment: one state; bounds: first through last. Boundary buttons retain their names when disabled. Navigation changes active regions, explanations, evidence, and status. Every state persists until action, including Grounded answer. Provide visible keyboard focus. Reference captures show Grounded answer."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the first state and all fixed defaults. Support Enter and Space with visible keyboard focus."
    }
  ],
  "data": {
    "variants": [
      {
        "label": "RAG with inspectable token-overlap retrieval",
        "regions": [
          {
            "id": "question",
            "label": "Question",
            "values": [
              "Is return shipping free for members?"
            ]
          },
          {
            "id": "returns",
            "label": "Returns",
            "values": [
              "Return shipping is free for members."
            ]
          },
          {
            "id": "outbound",
            "label": "Outbound",
            "values": [
              "Outbound shipping is free for all customers."
            ]
          },
          {
            "id": "retriever",
            "label": "Retriever",
            "values": [
              "Rank stored passages against the question"
            ]
          },
          {
            "id": "context",
            "label": "Retrieved context",
            "values": [
              "Selected source text"
            ]
          },
          {
            "id": "prompt",
            "label": "Augmented prompt",
            "values": [
              "Instructions + question + retrieved context"
            ]
          },
          {
            "id": "generator",
            "label": "Generator",
            "values": [
              "Generate from the augmented prompt"
            ]
          },
          {
            "id": "answer",
            "label": "Answer",
            "values": [
              "Response with a source citation"
            ]
          }
        ],
        "links": [
          {
            "from": "question",
            "to": "retriever",
            "label": "search query"
          },
          {
            "from": "returns",
            "to": "retriever",
            "label": "candidate passage"
          },
          {
            "from": "outbound",
            "to": "retriever",
            "label": "candidate passage"
          },
          {
            "from": "retriever",
            "to": "context",
            "label": "selected passage"
          },
          {
            "from": "context",
            "to": "prompt",
            "label": "source text"
          },
          {
            "from": "question",
            "to": "prompt",
            "label": "original question"
          },
          {
            "from": "prompt",
            "to": "generator",
            "label": "model input"
          },
          {
            "from": "generator",
            "to": "answer",
            "label": "generated response"
          }
        ],
        "states": [
          {
            "id": "question-ready",
            "label": "Question and sources",
            "short": "Ask",
            "sentence": "The Question enters a pipeline connected to the Returns and Outbound passages.",
            "why": "The stored passages provide external information that the Retriever can select before generation.",
            "active": [
              "question",
              "returns",
              "outbound"
            ],
            "calloutRegion": "question",
            "readouts": [
              {
                "id": "fixed-inputs",
                "label": "Fixed inputs",
                "value": "The question and both passages remain unchanged throughout this example."
              },
              {
                "id": "retrieval-setting",
                "label": "Retrieval setting",
                "value": "Top-k = 1 passage; ties choose Returns before Outbound."
              },
              {
                "id": "assumptions",
                "label": "Assumptions",
                "value": "Use transparent lexical retrieval and a fixed illustrative generator; no browsing or training occurs."
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Inputs are ready; no passage has been selected or supplied to the Generator."
              }
            ]
          },
          {
            "id": "rank-passages",
            "label": "Score candidate passages",
            "short": "Rank",
            "sentence": "The Retriever compares shared question tokens with each candidate passage.",
            "why": "This example uses inspectable token overlap; production retrievers often use embeddings, keyword search, or both.",
            "active": [
              "question",
              "returns",
              "outbound",
              "retriever"
            ],
            "calloutRegion": "retriever",
            "readouts": [
              {
                "id": "tokenization",
                "label": "Tokenization T",
                "value": "Lowercase, strip punctuation, split whitespace, remove {is, for, a, the}, and deduplicate tokens."
              },
              {
                "id": "score-rule",
                "label": "Score rule",
                "value": "s(d,q) = |T(d) ∩ T(q)|, measured in distinct tokens; higher scores rank first."
              },
              {
                "id": "returns-score",
                "label": "Returns overlap → score",
                "value": "{return, shipping, free, members} → 4 tokens"
              },
              {
                "id": "outbound-score",
                "label": "Outbound overlap → score",
                "value": "{shipping, free} → 2 tokens"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Returns ranks above Outbound under the declared scoring rule."
              }
            ]
          },
          {
            "id": "select-context",
            "label": "Retrieve the best passage",
            "short": "Retrieve",
            "sentence": "The Retriever places Returns into Retrieved context and excludes Outbound.",
            "why": "The selected passage directly addresses return shipping for members, rather than outbound shipping for customers.",
            "active": [
              "retriever",
              "returns",
              "context"
            ],
            "calloutRegion": "context",
            "readouts": [
              {
                "id": "selection",
                "label": "Selection",
                "value": "argmax over passage scores → Returns"
              },
              {
                "id": "selected-context",
                "label": "Retrieved context [Returns]",
                "value": "Return shipping is free for members."
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Retrieval has selected evidence; the Generator has not produced an answer."
              }
            ]
          },
          {
            "id": "augment-prompt",
            "label": "Build the augmented prompt",
            "short": "Augment",
            "sentence": "The Augmented prompt combines the original Question with Retrieved context and an instruction to cite its source.",
            "why": "Retrieved text becomes part of the Generator's input, not an update to its weights.",
            "active": [
              "question",
              "context",
              "prompt"
            ],
            "calloutRegion": "prompt",
            "readouts": [
              {
                "id": "model-input",
                "label": "Generator input",
                "value": "INSTRUCTION: Answer only from CONTEXT and cite its source; otherwise say you do not know.\nQUESTION: Is return shipping free for members?\nCONTEXT [Returns]: Return shipping is free for members."
              },
              {
                "id": "status",
                "label": "Status",
                "value": "The augmented prompt is ready; Outbound is absent, and the Generator's weights remain unchanged."
              }
            ]
          },
          {
            "id": "grounded-answer",
            "label": "Grounded answer",
            "short": "Answer",
            "sentence": "The Generator produces an Answer whose citation points back to Returns through Retrieved context.",
            "why": "Comparing the response with its supplied source makes the grounding visible; retrieval alone does not guarantee correctness.",
            "active": [
              "returns",
              "context",
              "generator",
              "answer"
            ],
            "calloutRegion": "answer",
            "readouts": [
              {
                "id": "source-evidence",
                "label": "Supplied evidence [Returns]",
                "value": "Return shipping is free for members."
              },
              {
                "id": "generated-answer",
                "label": "Illustrative generated answer",
                "value": "Yes—members receive free return shipping. [Returns]"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "The supplied passage supports the cited answer; model weights were not updated."
              }
            ]
          }
        ]
      }
    ]
  }
}
